import{_ as a,I as t,g as s,j as o}from"./chunks/framework.CjoWWfVe.js";const p=JSON.parse('{"title":"Capital (Balance Sheet)","description":"How OmniCraft ERP calculates your net worth, asset distribution, and personal investments.","frontmatter":{"title":"Capital (Balance Sheet)","description":"How OmniCraft ERP calculates your net worth, asset distribution, and personal investments.","order":11},"headers":[],"relativePath":"docs/spaces/production/capital.md","filePath":"docs/spaces/production/capital.md"}'),i={name:"docs/spaces/production/capital.md"};function r(n,e,l,h,u,c){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="💼-capital-the-business-balance-sheet" tabindex="-1">💼 Capital: The Business Balance Sheet <a class="header-anchor" href="#💼-capital-the-business-balance-sheet" aria-label="Permalink to &quot;💼 Capital: The Business Balance Sheet&quot;">​</a></h1><p>The <strong>&quot;Capital&quot;</strong> tab represents the financial pulse of your business in real time. Unlike the Cash Flow Ledger, which logs the movement of liquid money, Capital answers the owner&#39;s primary question: <strong>&quot;What is my business worth right now if I decide to close or sell it?&quot;</strong>.</p><p>Here, the program automatically aggregates all tangible assets owned by the workshop and subtracts external liabilities to determine your <strong>Equity (Net Worth)</strong>.</p><hr><h2 id="📊-the-main-figure-total-business-capital" tabindex="-1">📊 The Main Figure: Total Business Capital <a class="header-anchor" href="#📊-the-main-figure-total-business-capital" aria-label="Permalink to &quot;📊 The Main Figure: Total Business Capital&quot;">​</a></h2><p>At the very top of the screen, you see a large number representing the net value of your business. It is calculated using the fundamental formula of management accounting:</p><p>$$\\text{Capital} = \\text{All Workshop Assets} - \\text{Liabilities (Debts)}$$</p><p>If this figure is positive and increases from month to month, your business is growing wealthier, even if you currently have little liquid cash in your register (for example, if you purchased a large volume of leather in bulk or bought a new machine).</p><hr><h2 id="🥧-asset-distribution-business-structure" tabindex="-1">🥧 Asset Distribution (Business Structure) <a class="header-anchor" href="#🥧-asset-distribution-business-structure" aria-label="Permalink to &quot;🥧 Asset Distribution (Business Structure)&quot;">​</a></h2><p>Beneath the main figure, the program visually displays <strong>how your funds are currently allocated</strong>. Business assets are divided into four primary categories, each represented by a progress bar with its percentage share:</p><h3 id="_1-💵-free-cash" tabindex="-1">1. 💵 Free Cash <a class="header-anchor" href="#_1-💵-free-cash" aria-label="Permalink to &quot;1. 💵 Free Cash&quot;">​</a></h3><p>This is your current positive Cash Flow balance. Liquid funds physically sitting in bank accounts or cash drawers, ready for immediate use (paying wages, making new purchases, or withdrawing as profit).</p><h3 id="_2-📦-raw-materials-in-stock" tabindex="-1">2. 📦 Raw Materials in Stock <a class="header-anchor" href="#_2-📦-raw-materials-in-stock" aria-label="Permalink to &quot;2. 📦 Raw Materials in Stock&quot;">​</a></h3><p>The total value of all raw materials, calculated using the <strong>MAC (Moving Average Cost)</strong> method. This represents your cash &quot;frozen&quot; in the form of leather, thread, glue, and thread that has not yet been processed into finished goods.</p><h3 id="_3-🛍️-finished-goods-on-the-showcase" tabindex="-1">3. 🛍️ Finished Goods on the Showcase <a class="header-anchor" href="#_3-🛍️-finished-goods-on-the-showcase" aria-label="Permalink to &quot;3. 🛍️ Finished Goods on the Showcase&quot;">​</a></h3><p>The value of products you have already crafted but have not yet sold. These are valued at their actual manufacturing cost price (factoring in FIFO batches). Once an item is sold, its value flows out of this block and into free cash (revenue) and net profit.</p><h3 id="_4-🛠️-equipment-tools-workshop" tabindex="-1">4. 🛠️ Equipment &amp; Tools (Workshop) <a class="header-anchor" href="#_4-🛠️-equipment-tools-workshop" aria-label="Permalink to &quot;4. 🛠️ Equipment &amp; Tools (Workshop)&quot;">​</a></h3><p>The residual value of all your machinery, presses, and expensive tools, adjusted for accumulated depreciation. This is your production foundation.</p><hr><h2 id="🛡️-personal-investments-negative-cash-flow" tabindex="-1">🛡️ Personal Investments (Negative Cash Flow) <a class="header-anchor" href="#🛡️-personal-investments-negative-cash-flow" aria-label="Permalink to &quot;🛡️ Personal Investments (Negative Cash Flow)&quot;">​</a></h2><p>Occasionally, within the asset distribution block, you may see a red card: <strong>&quot;Personal Investments&quot;</strong>.</p><p><strong>What does this mean?</strong> Under the <em>mixed finances</em> philosophy of OmniCraft ERP, a negative Cash Flow Ledger balance is perfectly normal. It indicates that at the beginning or during cash crunches, you injected <strong>your own personal funds</strong> (e.g., from a personal bank card) to purchase raw materials or equipment for the workshop. The program records this contribution.</p><ul><li><strong>How it works:</strong> If your Cash Flow is negative by <code>$5,000</code>, the program displays this as &quot;Personal Investments&quot;. This means the business &quot;owes&quot; you <code>$5,000</code>.</li><li><strong>When will it disappear?</strong> As soon as the business begins generating stable profits and the Cash Flow balance crosses the zero mark, the &quot;Personal Investments&quot; card will disappear, indicating the business has fully returned your personal funds and is operating on its own self-sufficiency.</li></ul><div class="tip custom-block"><p class="custom-block-title">How to Read Capital and Cash Flow Together</p><ul><li><strong>Cash Flow</strong> shows how much <strong>liquid money</strong> you have right now to pay bills.</li><li><strong>Capital</strong> shows how <strong>wealthy your business is</strong> overall (machinery + raw materials on shelves + completed showroom inventory + cash in register).</li></ul></div>',25)])])}const g=a(i,[["render",r]]);export{p as __pageData,g as default};
